import type { SlateElementProps, SlateLeafProps } from 'platejs/static';
import { SlateElement, SlateLeaf } from 'platejs/static';
import type { ReactElement } from 'react';

export const codeBlockClassName = [
    'my-2 overflow-x-auto rounded-lg bg-muted px-4 py-3 font-mono text-sm leading-6 [tab-size:2]',
    '[&_.hljs-comment,&_.hljs-quote]:text-muted-foreground [&_.hljs-comment,&_.hljs-quote]:italic',
    '[&_.hljs-keyword,&_.hljs-selector-tag,&_.hljs-built_in]:text-violet-600 dark:[&_.hljs-keyword,&_.hljs-selector-tag,&_.hljs-built_in]:text-violet-400',
    '[&_.hljs-string,&_.hljs-regexp,&_.hljs-addition]:text-emerald-700 dark:[&_.hljs-string,&_.hljs-regexp,&_.hljs-addition]:text-emerald-400',
    '[&_.hljs-number,&_.hljs-literal,&_.hljs-variable,&_.hljs-template-variable]:text-amber-700 dark:[&_.hljs-number,&_.hljs-literal,&_.hljs-variable,&_.hljs-template-variable]:text-amber-400',
    '[&_.hljs-title,&_.hljs-section,&_.hljs-name,&_.hljs-attr,&_.hljs-attribute]:text-sky-700 dark:[&_.hljs-title,&_.hljs-section,&_.hljs-name,&_.hljs-attr,&_.hljs-attribute]:text-sky-400',
    '[&_.hljs-deletion]:text-destructive',
].join(' ');

export function CodeBlockElementStatic({
    children,
    ...props
}: SlateElementProps): ReactElement {
    return (
        <SlateElement {...props} className={codeBlockClassName}>
            <pre className="m-0">
                <code>{children}</code>
            </pre>
        </SlateElement>
    );
}

export function CodeLineElementStatic(props: SlateElementProps): ReactElement {
    return <SlateElement {...props} />;
}

export function syntaxClassName(className: unknown): string | undefined {
    if (typeof className !== 'string') {
        return undefined;
    }

    return (
        className
            .split(/\s+/)
            .filter((name) => /^hljs(-[\w-]+)?$/.test(name))
            .join(' ') || undefined
    );
}

export function CodeSyntaxLeafStatic(props: SlateLeafProps): ReactElement {
    return (
        <SlateLeaf
            {...props}
            className={syntaxClassName(props.leaf.className)}
        />
    );
}

import type { SlateLeafProps } from 'platejs/static';
import { SlateLeaf } from 'platejs/static';
import type { ReactElement } from 'react';

export const codeLeafClassName =
    'whitespace-pre-wrap rounded-md bg-muted px-[0.3em] py-[0.2em] font-mono text-[0.875em]';

export function CodeLeafStatic(props: SlateLeafProps): ReactElement {
    return <SlateLeaf {...props} as="code" className={codeLeafClassName} />;
}

import { createStaticEditor, PlateStatic } from 'platejs/static';
import type { ReactElement } from 'react';
import { useMemo } from 'react';
import { BaseEditorKit } from '@/components/editor/base-editor-kit';
import type { EditorValue } from '@/components/editor/editor-value';
import { cn } from '@/lib/utils';

export const editorContentClassName =
    'relative w-full whitespace-break-spaces break-words text-base text-foreground [&_strong]:font-semibold';

export type EditorStaticProps = {
    value: EditorValue;
    className?: string;
};

export function EditorStatic({
    value,
    className,
}: EditorStaticProps): ReactElement {
    const editor = useMemo(
        () => createStaticEditor({ plugins: BaseEditorKit, value }),
        [value],
    );

    return (
        <PlateStatic
            className={cn(editorContentClassName, className)}
            editor={editor}
        />
    );
}

const LINK_PROTOCOLS = ['http:', 'https:', 'mailto:'];
const IMAGE_PROTOCOLS = ['http:', 'https:'];

export const LINK_SCHEMES = LINK_PROTOCOLS.map((protocol) =>
    protocol.slice(0, -1),
);

function hasProtocol(url: unknown, protocols: string[]): boolean {
    if (typeof url !== 'string') {
        return false;
    }

    try {
        return protocols.includes(new URL(url.trim()).protocol);
    } catch {
        return false;
    }
}

export function isAllowedLinkUrl(url: unknown): boolean {
    return hasProtocol(url, LINK_PROTOCOLS);
}

export function isAllowedImageUrl(url: unknown): boolean {
    return hasProtocol(url, IMAGE_PROTOCOLS);
}

import type { Descendant, Value } from 'platejs';

export type EditorValue = Value;

export const EMPTY_EDITOR_VALUE: EditorValue = [
    { type: 'p', children: [{ text: '' }] },
];

function hasContent(node: Descendant): boolean {
    if ('text' in node) {
        return typeof node.text === 'string' && node.text.trim() !== '';
    }

    if (node.type === 'img' || node.type === 'hr' || node.type === 'table') {
        return true;
    }

    return node.children.some((child) => hasContent(child as Descendant));
}

export function isEditorValueEmpty(
    value: EditorValue | null | undefined,
): boolean {
    return !value?.some((node) => hasContent(node));
}

import { cva } from 'class-variance-authority';
import type { SlateElementProps } from 'platejs/static';
import { SlateElement } from 'platejs/static';
import type { ReactElement } from 'react';

export type HeadingLevel = 'h2' | 'h3' | 'h4';

export const headingVariants = cva(
    'relative mb-1 font-heading font-semibold text-foreground tracking-tight',
    {
        variants: {
            variant: {
                h2: 'mt-[1.4em] pb-px text-2xl',
                h3: 'mt-[1.2em] pb-px text-xl',
                h4: 'mt-[1em] text-lg',
            },
        },
    },
);

function HeadingElementStatic({
    variant,
    ...props
}: SlateElementProps & { variant: HeadingLevel }): ReactElement {
    return (
        <SlateElement
            {...props}
            as={variant}
            className={headingVariants({ variant })}
        />
    );
}

export function H2ElementStatic(props: SlateElementProps): ReactElement {
    return <HeadingElementStatic {...props} variant="h2" />;
}

export function H3ElementStatic(props: SlateElementProps): ReactElement {
    return <HeadingElementStatic {...props} variant="h3" />;
}

export function H4ElementStatic(props: SlateElementProps): ReactElement {
    return <HeadingElementStatic {...props} variant="h4" />;
}

import type { SlateElementProps } from 'platejs/static';
import { SlateElement } from 'platejs/static';
import type { ReactElement } from 'react';

export const hrClassName = 'h-px rounded-full border-none bg-border';

export function HrElementStatic(props: SlateElementProps): ReactElement {
    return (
        <SlateElement {...props}>
            <div className="py-6" contentEditable={false}>
                <hr className={hrClassName} />
            </div>
            {props.children}
        </SlateElement>
    );
}

import type { TImageElement } from 'platejs';
import type { SlateElementProps } from 'platejs/static';
import { SlateElement } from 'platejs/static';
import type { ReactElement } from 'react';
import { isAllowedImageUrl } from '@/components/editor/editor-url';

export const imageClassName =
    'block h-auto max-w-full rounded-lg outline outline-1 -outline-offset-1 outline-black/10 dark:outline-white/10';

export function ImageElementStatic(
    props: SlateElementProps<TImageElement>,
): ReactElement {
    const { url, alt } = props.element as TImageElement & { alt?: string };

    return (
        <SlateElement {...props} className="py-2.5">
            <figure className="m-0" contentEditable={false}>
                {isAllowedImageUrl(url) ? (
                    <img
                        alt={alt ?? ''}
                        className={imageClassName}
                        loading="lazy"
                        src={url}
                    />
                ) : null}
            </figure>
            {props.children}
        </SlateElement>
    );
}

import { getLinkAttributes } from '@platejs/link';
import type { TLinkElement } from 'platejs';
import type { SlateElementProps } from 'platejs/static';
import { SlateElement } from 'platejs/static';
import type { ReactElement } from 'react';
import { isAllowedLinkUrl } from '@/components/editor/editor-url';

export const linkClassName =
    'font-medium text-primary underline decoration-primary/40 underline-offset-4 hover:decoration-primary';

export function LinkElementStatic(
    props: SlateElementProps<TLinkElement>,
): ReactElement {
    return (
        <SlateElement
            {...props}
            as="a"
            attributes={{
                ...props.attributes,
                ...(isAllowedLinkUrl(props.element.url)
                    ? getLinkAttributes(props.editor, props.element)
                    : {}),
            }}
            className={linkClassName}
        />
    );
}

import type { SlateElementProps } from 'platejs/static';
import { SlateElement } from 'platejs/static';
import type { ReactElement } from 'react';

export const paragraphClassName = 'm-0 px-0 py-1 leading-7';

export function ParagraphElementStatic(props: SlateElementProps): ReactElement {
    return <SlateElement {...props} className={paragraphClassName} />;
}

import { BaseTablePlugin } from '@platejs/table';
import type { TTableCellElement, TTableElement } from 'platejs';
import type { SlateElementProps } from 'platejs/static';
import { SlateElement } from 'platejs/static';
import type { ReactElement } from 'react';
import { cn } from '@/lib/utils';

export const tableClassName =
    'w-full table-fixed border-collapse text-sm [&_td]:align-top [&_th]:align-top';

export const tableCellClassName =
    'border border-border px-3 py-2 text-left [&>*]:m-0';

export function TableElementStatic({
    children,
    ...props
}: SlateElementProps<TTableElement>): ReactElement {
    return (
        <SlateElement {...props} className="my-4 overflow-x-auto">
            <table className={tableClassName}>
                <tbody>{children}</tbody>
            </table>
        </SlateElement>
    );
}

export function TableRowElementStatic(props: SlateElementProps): ReactElement {
    return <SlateElement {...props} as="tr" />;
}

function TableCell({
    isHeader,
    ...props
}: SlateElementProps<TTableCellElement> & {
    isHeader?: boolean;
}): ReactElement {
    const { api } = props.editor.getPlugin(BaseTablePlugin);

    return (
        <SlateElement
            {...props}
            as={isHeader ? 'th' : 'td'}
            attributes={{
                ...props.attributes,
                colSpan: api.table.getColSpan(props.element),
                rowSpan: api.table.getRowSpan(props.element),
            }}
            className={cn(
                tableCellClassName,
                isHeader && 'bg-muted/60 font-medium',
            )}
        />
    );
}

export function TableCellElementStatic(
    props: SlateElementProps<TTableCellElement>,
): ReactElement {
    return <TableCell {...props} />;
}

export function TableCellHeaderElementStatic(
    props: SlateElementProps<TTableCellElement>,
): ReactElement {
    return <TableCell {...props} isHeader />;
}
